import { createCourseBuilder } from '../CourseBuilder';
import { defineHole } from '../Hole';

const v = (x: number, y: number, z: number) => ({ x, y, z });
const floor = (id: string, x: number, z: number, sx: number, sz: number, material: 'green' | 'rough' | 'sand' = 'green', y = 0) => ({ id, transform: { position: v(x, y, z) }, shape: 'box' as const, size: v(sx, 0.4, sz), material });
const wall = (id: string, x: number, z: number, sx: number, sz: number) => ({ id, type: 'wall' as const, transform: { position: v(x, 0.7, z) }, size: v(sx, 1.4, sz), restitution: 0.35 });
const water = (id: string, x: number, z: number, sx: number, sz: number) => ({ id, type: 'water' as const, transform: { position: v(x, 0.1, z) }, size: v(sx, 0.4, sz), penaltyStrokes: 1 });
const bounds = (w: number, l: number) => ({ min: v(-w / 2 - 2, -4, -2), max: v(w / 2 + 2, 8, l + 2) });
const cup = (x: number, z: number) => ({ position: v(x, 0.35, z), radius: 0.32, captureDepth: 0.35 });

